type Stats={spend:number;results:number;impressions:number;clicks:number;reach:number;frequency:number;video3s:number;thruplays:number;rows:number};
function stats(rows:OfflineRow[]):Stats{const spend=rows.reduce((sum,row)=>sum+row.spend,0),results=rows.reduce((sum,row)=>sum+row.results,0),impressions=rows.reduce((sum,row)=>sum+row.impressions,0),clicks=rows.reduce((sum,row)=>sum+(row.link_clicks??0),0),reach=rows.reduce((sum,row)=>sum+(row.reach??0),0),frequencyWeight=rows.reduce((sum,row)=>sum+(row.frequency??0)*Math.max(1,row.impressions),0),frequencyDenom=rows.reduce((sum,row)=>sum+(row.frequency===null?0:Math.max(1,row.impressions)),0);return {spend,results,impressions,clicks,reach,frequency:frequencyDenom?frequencyWeight/frequencyDenom:0,video3s:rows.reduce((sum,row)=>sum+(row.video_3s??0),0),thruplays:rows.reduce((sum,row)=>sum+(row.thruplays??0),0),rows:rows.length}}
function rate(n:number,d:number){return d?n/d*100:0}
function compareText(current:number,previous:number,unit=''){if(!previous)return 'Tidak ada periode pembanding';const delta=(current-previous)/previous*100;return `${delta>0?'Naik':delta<0?'Turun':'Tetap'} ${Math.abs(delta).toFixed(1)}%${unit}`}
