function OfflineMetric({label,value,note,icon:Icon}:{label:string;value:string;note:string;icon:typeof Activity}){return <Card className="offline-metric"><div><span>{label}</span><b>{value}</b><small>{note}</small></div><i><Icon size={17}/></i></Card>}
